/* ======================================================================
   CHAMPION
====================================================================== */

function ChampionReveal({ league, photos, myId, rows }) {
  const [shown, setShown] = useState(false);
  const champ = league.players.find((p) => p.id === league.champion);

  useEffect(() => {
    const t = setTimeout(() => setShown(true), 1800);
    return () => clearTimeout(t);
  }, []);

  if (!shown)
    return (
      <div style={{ height: "100vh", display: "grid", placeItems: "center", padding: 30, background: "#160D24" }}>
        <div className="marquee" style={{ fontSize: 23, color: "var(--champagne)", textAlign: "center", lineHeight: 1.3 }}>
          THE {league.season} FANTASY<br />MIRRORBALL CHAMPION IS…
        </div>
      </div>
    );

  return (
    <div style={{ padding: "64px 22px 40px", textAlign: "center" }}>
      <div style={{ fontSize: 54, filter: "drop-shadow(0 0 24px rgba(242,193,78,.6))" }}>🏆</div>
      <div className="marquee" style={{ fontSize: 34, color: "var(--gold)", margin: "10px 0 2px" }}>
        {champ.name.toUpperCase()}
      </div>
      <div style={{ color: "var(--champagne)", fontWeight: 700, marginBottom: 34 }}>
        {rows[0].total} points · {champ.team}
      </div>

      <div style={{ textAlign: "left" }}>
        <SectionLabel>Final standings</SectionLabel>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {rows.map((r, i) => <StandingRow key={r.player.id} rank={i + 1} player={r.player} pts={r.total} myId={myId} />)}
        </div>
        <Recap league={league} photos={photos} />
      </div>
    </div>
  );
}

function Recap({ league, photos }) {
  const players = league.players;

  let psychic = players[0], best = -1;
  players.forEach((p) => {
    let n = 0;
    for (let w = 1; w <= league.week; w++) {
      const wd = league.weeklyData[w];
      const gone = elimsFor(wd);
      n += predsFor(wd, p.id).filter((id) => gone.includes(id)).length;
    }
    if (n > best) { best = n; psychic = p; }
  });

  let bestDraft = players[0], bestPts = -1;
  players.forEach((p) => {
    const pts = playerCouples(league, p.id).reduce((s, c) => s + coupleSeasonPoints(league, c.id), 0);
    if (pts > bestPts) { bestPts = pts; bestDraft = p; }
  });

  let gem = null, gemRatio = -1;
  league.couples.forEach((c) => {
    const ratio = coupleSeasonPoints(league, c.id) * (c.draftPos || 16);
    if (ratio > gemRatio) { gemRatio = ratio; gem = c; }
  });

  let bust = null;
  league.couples
    .filter((c) => c.eliminatedWeek && c.draftPos <= 6)
    .sort((a, b) => a.eliminatedWeek - b.eliminatedWeek)
    .slice(0, 1)
    .forEach((c) => { bust = c; });

  let bw = { p: null, w: 0, s: -1 };
  for (let w = 1; w <= league.week; w++) {
    if (!league.weeklyData[w]?.finalized) continue;
    players.forEach((p) => {
      const s = playerWeekScore(league, p.id, w);
      if (s > bw.s) bw = { p, w, s };
    });
  }

  const awards = [
    { icon: "💎", t: "Best value pick", d: gem ? `${gem.celeb} & ${gem.pro}, taken #${gem.draftPos} for ${coupleSeasonPoints(league, gem.id)} points.` : null, couple: gem },
    bust ? { icon: "💀", t: "Draft bust", d: `${bust.celeb} & ${bust.pro} went out week ${bust.eliminatedWeek} after an early pick.`, couple: bust } : null,
    { icon: "🔮", t: "Psychic award", d: `${psychic.name} called ${best} elimination${best === 1 ? "" : "s"} right.` },
    { icon: "🐍", t: "Best draft", d: `${bestDraft.name}'s four couples scored ${bestPts} between them.` },
    bw.p ? { icon: "🔥", t: "Best week", d: `${bw.p.name} put up ${bw.s} in week ${bw.w}.` } : null,
  ].filter((a) => a && a.d);

  return (
    <div style={{ marginTop: 30 }}>
      <SectionLabel>Season awards</SectionLabel>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {awards.map((a, i) => (
          <div key={i} className="card" style={{ padding: 12, display: "flex", gap: 12, alignItems: "center" }}>
            {a.couple ? <Portrait couple={a.couple} photo={photoFor(photos, a.couple.id)} size={34} /> : <span style={{ fontSize: 22 }}>{a.icon}</span>}
            <div>
              <div style={{ fontWeight: 800, fontSize: 13.5 }}>{a.icon} {a.t}</div>
              <div style={{ fontSize: 12, color: "var(--muted)", lineHeight: 1.45 }}>{a.d}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ======================================================================
   RULES
====================================================================== */

function Rules() {
  const [tab, setTab] = useState("scoring");

  return (
    <div style={{ padding: "26px 18px" }}>
      <div className="marquee" style={{ fontSize: 25, color: "var(--violet)", marginBottom: 16 }}>RULES</div>
      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        {[["scoring", "Scoring"], ["league", "League"], ["example", "Example"]].map(([k, label]) => (
          <button key={k} className={tab === k ? "btn btn-primary" : "btn btn-secondary"}
            style={{ flex: 1, padding: 9, fontSize: 12.5 }} onClick={() => setTab(k)}>{label}</button>
        ))}
      </div>

      {tab === "scoring" && (
        <>
          <SectionLabel>Every way to score</SectionLabel>
          <div style={{ display: "flex", flexDirection: "column", gap: 9, marginBottom: 24 }}>
            <ScoreLine value="1 : 1" label="Judges' scores"
              detail="Each judges' point your couple earns is one fantasy point. A 26 is 26." />
            <ScoreLine value="all" label="Multiple dances"
              detail="Later in the season couples dance more than once. Every scored dance counts." />
            <ScoreLine value="+10" label="Weekly bonus"
              detail="Ten points a week to split across your active couples however you like." />
            <ScoreLine value="+5" label="Elimination call"
              detail="Five points for each couple you correctly call going home. The premiere is a double elimination, so pick one male celebrity and one female celebrity for up to ten points." />
            <ScoreLine value="+50" label="Finale champion" detail="Awarded to whoever owns the winning couple." />
            <ScoreLine value="+30" label="Finale runner-up" />
            <ScoreLine value="+20" label="Finale third place" />
            <ScoreLine value="+10" label="Finale fourth place" />
          </div>

          <SectionLabel>What doesn't score</SectionLabel>
          <div className="card" style={{ padding: 14, fontSize: 13, color: "var(--muted)", lineHeight: 1.6 }}>
            Eliminated couples stop earning the week they go home, but everything they already
            banked stays on your total. Season awards are for bragging rights and change nothing.
          </div>
        </>
      )}

      {tab === "league" && (
        <>
          <Rule t="Teams">Four players, sixteen couples, four each. A couple belongs to one owner all season.</Rule>
          <Rule t="Draft">Random order, four rounds, snake format. All sixteen couples go.</Rule>
          <Rule t="Rosters">Locked at the end of the draft. No trades, drops, free agents, or redrafts.</Rule>
          <Rule t="Weekly deadline">Bonus points and your elimination call are due by 7:55 PM ET Tuesday. Nothing changes after that.</Rule>
          <Rule t="Privacy">Nobody sees your bonus split or your prediction until every player has locked.</Rule>
          <Rule t="Predictions">Five points per correct call. The commissioner sets how many go home each week, so some weeks you call two and some weeks none at all. Hidden until everyone locks.</Rule>
          <Rule t="Premiere week">The premiere is a scheduled double elimination — call one male celebrity and one female celebrity going home, five points each.</Rule>
          <Rule t="Eliminations">A week can send home nobody, one couple, or several. An eliminated couple stays on your roster marked out, keeps its points, and stops earning.</Rule>
          <Rule t="Commissioner">Enters judges' scores, marks eliminations, records finale placements, and fixes typos. Cannot touch anyone's picks after lock or hand out points.</Rule>
          <Rule t="Winning">Highest total after the finale takes the Fantasy Mirrorball.</Rule>
        </>
      )}

      {tab === "example" && (
        <>
          <SectionLabel>One player, one week</SectionLabel>
          <div className="card" style={{ padding: 15, marginBottom: 16 }}>
            <ExRow label="Couple A judges' score" value="28" />
            <ExRow label="Couple B judges' score" value="25" />
            <ExRow label="Couple C judges' score" value="23" />
            <ExRow label="Couple D — eliminated week 2" value="0" muted />
            <div style={{ borderTop: "1px solid var(--line)", margin: "9px 0" }} />
            <ExRow label="Judges' subtotal" value="76" />
            <ExRow label="Weekly bonus (5 + 3 + 2)" value="+10" />
            <ExRow label="Called the elimination" value="+5" />
            <div style={{ borderTop: "1px solid var(--line)", margin: "9px 0" }} />
            <ExRow label="Week total" value="91" big />
          </div>
          <p style={{ fontSize: 12.5, color: "var(--muted)", lineHeight: 1.6 }}>
            Bonus points ride on couples who are still dancing, so a thin roster late in the
            season means stacking all ten on fewer names. Tap any score in the League tab to
            see this same breakdown for a real week.
          </p>
        </>
      )}
    </div>
  );
}

function ScoreLine({ value, label, detail }) {
  return (
    <div className="card" style={{ padding: 12, display: "flex", gap: 12, alignItems: "flex-start" }}>
      <div style={{
        minWidth: 52, textAlign: "center", padding: "6px 7px", borderRadius: 8,
        background: "linear-gradient(120deg,rgba(113,55,168,.14),rgba(215,45,145,.14))",
        color: "var(--violet)", fontWeight: 800, fontSize: 13.5,
      }}>{value}</div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5 }}>{label}</div>
        {detail && <div style={{ fontSize: 12, color: "var(--muted)", lineHeight: 1.5, marginTop: 2 }}>{detail}</div>}
      </div>
    </div>
  );
}

function ExRow({ label, value, big, muted }) {
  return (
    <div style={{
      display: "flex", justifyContent: "space-between", padding: "4px 0",
      fontSize: big ? 15 : 13.5, fontWeight: big ? 800 : 500,
      color: muted ? "var(--muted)" : "var(--text)",
    }}>
      <span>{label}</span>
      <span style={{ fontWeight: 800, color: big ? "var(--fuchsia)" : "inherit" }}>{value}</span>
    </div>
  );
}

/* ======================================================================
   NAV
====================================================================== */

function BottomNav({ tab, setTab }) {
  const items = [
    { id: "home", icon: <Trophy size={20} />, label: "Home" },
    { id: "team", icon: <Users size={20} />, label: "Team" },
    { id: "league", icon: <ListOrdered size={20} />, label: "League" },
    { id: "rules", icon: <ClipboardList size={20} />, label: "Rules" },
    { id: "more", icon: <MoreHorizontal size={20} />, label: "More" },
  ];
  return (
    <nav style={{
      position: "fixed", bottom: 0, left: "50%", transform: "translateX(-50%)",
      width: "100%", maxWidth: 480, background: "#FFFFFF",
      borderTop: "1px solid rgba(113,55,168,.16)", display: "flex",
      padding: "10px 6px 18px", zIndex: 50,
    }}>
      {items.map((it) => (
        <button key={it.id} onClick={() => setTab(it.id)} style={{
          flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
          background: "transparent", border: "none", cursor: "pointer",
          color: tab === it.id ? "#D72D91" : "#7A6591", fontSize: 10.5, fontWeight: 700,
          fontFamily: "'Manrope',sans-serif",
        }}>
          {it.icon}{it.label}
        </button>
      ))}
    </nav>
  );
}
